#include "Epidemic/GameFramework/Economy/economy.h"
#include <cstdlib>
#include <iostream>
using namespace epidemic::gameplay;using namespace epidemic::gameplay::economy;
namespace{void Check(bool v,const char*m){if(!v){std::cerr<<m<<'\n';std::exit(1);}}GameplayObjectRef Ref(const char*d,const char*i){return {GameplayDomainId::FromString(d),GameplayObjectId::FromString(i)};}class Price final:public IPriceProvider{public:std::optional<PriceQuote> Quote(EconomicValueRef s,CurrencyId c,GameplayObjectRef,GameplayObjectRef)const override{return PriceQuote{s,c,123,Revision{7}};}};}
int main(){EconomyService s;CurrencyDefinition coin;coin.canonical_name="currency.coin";auto cid=s.RegisterCurrency(coin);Check(static_cast<bool>(cid),"currency");s.Freeze();EconomicAccount buyer;buyer.owner=Ref("actor","buyer");buyer.currency=cid.Value();buyer.balance=1000;auto bid=s.CreateAccount(buyer);Check(static_cast<bool>(bid),"buyer account");EconomicAccount seller;seller.owner=Ref("actor","seller");seller.currency=cid.Value();seller.balance=50;auto sid=s.CreateAccount(seller);Check(static_cast<bool>(sid),"seller account");auto reserve=s.ReserveFunds(bid.Value(),200,seller.owner);Check(static_cast<bool>(reserve),"reserve funds");Check(s.GetAvailableBalance(bid.Value())==800,"available balance");Check(static_cast<bool>(s.CommitFunds(reserve.Value(),sid.Value())),"commit funds");Check(s.GetBalance(bid.Value())==800&&s.GetBalance(sid.Value())==250,"funds moved");TradePlan plan;plan.buyer=buyer.owner;plan.seller=seller.owner;plan.monetary_transfers.push_back({bid.Value(),sid.Value(),100,cid.Value()});auto tx=s.PrepareTrade(plan);Check(static_cast<bool>(tx),"prepare trade");Check(static_cast<bool>(s.ReserveTrade(tx.Value())),"reserve trade");Check(static_cast<bool>(s.CommitTrade(tx.Value())),"commit trade");Check(s.GetBalance(bid.Value())==700&&s.GetBalance(sid.Value())==350,"trade funds moved");MarketState market;market.area=Ref("area","city");auto mid=s.CreateMarket(market);Check(static_cast<bool>(mid),"market");auto commodity=EconomicCommodityId::FromString("commodity.food");Check(static_cast<bool>(s.SetMarketIndicator({mid.Value(),commodity,10,20,1'200'000,GameplayTimePoint{10},{}})),"indicator");Check(s.GetMarketIndicator(mid.Value(),commodity)->price_index_micro==1'200'000,"indicator stored");Price price;s.AddPriceProvider(&price);EconomicValueRef value;value.type=EconomicValueTypeId::FromString("item");value.definition=TypeId::FromString("item.apple");Check(s.GetPriceQuote(value,cid.Value())->amount==123,"price provider");DebtRecord debt;debt.debtor=buyer.owner;debt.creditor=seller.owner;debt.currency=cid.Value();debt.principal=500;auto debtid=s.CreateDebt(debt);Check(static_cast<bool>(debtid),"debt");auto snap=s.CaptureSnapshot();EconomyService restored;Check(static_cast<bool>(restored.RegisterCurrency(coin)),"restore currency def");restored.Freeze();Check(static_cast<bool>(restored.RestoreSnapshot(std::move(snap))),"restore economy");Check(restored.GetBalance(bid.Value())==700,"balance restored");Check(restored.FindDebts(buyer.owner).size()==1,"debt restored");return 0;}
